def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3') or (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3') or 0.0
    if v <= 0:
        sites = s.get('sites') or []
        count = sum(max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites)
        volume = (s.get('lattice') or {}).get('volume_A3') or 0.0
        v = volume / count if count > 0 else 0.0
    return log1p(v) if v > 0 and isfinite(v) else 0.0

def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3') or (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3') or 0.0
    if v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    coverage = 0.0
    for el, x in (s.get('composition') or {}).items():
        r = (props.get(el) or {}).get('covalent_radius_A')
        if r is not None and r > 0 and x is not None and x > 0:
            total += x * r * r * r
            coverage += x
    return 4.0 * pi * total / (3.0 * coverage * v) if coverage > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') or 0.0 for t in sites]
    nearest = [inf] * n
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 0 and occ[i] > 0 and occ[j] > 0 and radii[i] > 0 and radii[j] > 0:
            nearest[i] = min(nearest[i], d / (radii[i] + radii[j]))
    w = sum(occ[i] for i in range(n) if isfinite(nearest[i]))
    return sum(occ[i] * nearest[i] for i in range(n) if isfinite(nearest[i])) / w if w > 0 else 0.0

