def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    nearest = [inf] * n
    bonds = s.get('neighbors') or []
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 0 and occ[i] > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    coordination = [0.0] * n
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 0 and d <= 1.25 * nearest[i]:
            coordination[i] += occ[j]
    w = sum(occ)
    if w <= 0:
        return 0.0
    mean = sum(occ[i] * coordination[i] for i in range(n)) / w
    return sqrt(sum(occ[i] * (coordination[i] - mean) ** 2 for i in range(n)) / w)

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    elements = [t.get('element') for t in sites]
    count = sum(occ)
    if count <= 0:
        return 0.0
    fractions = {}
    for i in range(n):
        fractions[elements[i]] = fractions.get(elements[i], 0.0) + occ[i] / count
    expected = 1.0 - sum(x * x for x in fractions.values())
    nearest = [inf] * n
    bonds = s.get('neighbors') or []
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 0 and occ[i] > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    hetero = 0.0
    total = 0.0
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 0 and d <= 1.25 * nearest[i]:
            w = occ[i] * occ[j]
            total += w
            if elements[i] != elements[j]:
                hetero += w
    return hetero / total - expected if total > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    count = sum(occ)
    if count <= 0:
        return 0.0
    radii = []
    eligible = []
    for t in sites:
        p = props.get(t.get('element')) or {}
        radii.append(p.get('covalent_radius_A') or 0.0)
        en = p.get('eneg')
        eligible.append(en is not None and en >= 2.0 and ((p.get('group') or 0) >= 14 or p.get('Z') == 1))
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 0 and eligible[i] and sites[i].get('element') == sites[j].get('element') and radii[i] > 0 and radii[j] > 0 and d <= 1.25 * (radii[i] + radii[j]):
            total += occ[i] * occ[j]
    return 0.5 * total / count

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    ionization = [(props.get(t.get('element')) or {}).get('first_ionization_energy_eV') for t in sites]
    affinity = [(props.get(t.get('element')) or {}).get('electron_affinity_eV') for t in sites]
    nearest = [inf] * n
    bonds = s.get('neighbors') or []
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 0 and occ[i] > 0 and occ[j] > 0:
            nearest[i] = min(nearest[i], d)
    total = 0.0
    weight = 0.0
    for b in bonds:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 0 and d <= 1.25 * nearest[i]:
            gaps = []
            if ionization[i] is not None and affinity[j] is not None:
                gaps.append(ionization[i] - affinity[j])
            if ionization[j] is not None and affinity[i] is not None:
                gaps.append(ionization[j] - affinity[i])
            if gaps:
                w = occ[i] * occ[j]
                total += w * min(gaps)
                weight += w
    return total / weight if weight > 0 else 0.0

def feature(s):
    s = s or {}
    v = s.get('volume_per_atom_A3') or (s.get('basic_structure_statistics') or {}).get('volume_per_atom_A3') or 0.0
    if v <= 0:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    coverage = 0.0
    for el, x in (s.get('composition') or {}).items():
        valence = (props.get(el) or {}).get('valence_electrons')
        if valence is not None and x is not None and x > 0:
            total += x * valence
            coverage += x
    return total / (coverage * v) if coverage > 0 else 0.0

def feature(s):
    s = s or {}
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    first = [inf] * n
    second = [inf] * n
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 0 and occ[i] > 0 and occ[j] > 0:
            if d < first[i]:
                second[i] = first[i]
                first[i] = d
            elif d < second[i]:
                second[i] = d
    total = 0.0
    weight = 0.0
    for i in range(n):
        if isfinite(first[i]):
            next_distance = second[i] if isfinite(second[i]) else 6.0
            total += occ[i] * (min(10.0, next_distance / first[i]) - 1.0)
            weight += occ[i]
    return total / weight if weight > 0 else 0.0
